   if (error != NO_ERROR)
     {
-      return error;
+      goto cleanup;
     }

   assert (result != NULL);
@@ -3512,7 +3527,8 @@ partition_find_partition_for_expr (THREAD_ENTRY * thread_p, PRUNING_CONTEXT * pi
   if (status != MATCH_OK)
     {
       er_set (ER_ERROR_SEVERITY, ARG_FILE_LINE, ER_PARTITION_NOT_EXIST, 0);
-      return ER_PARTITION_NOT_EXIST;
